 <script>
 const colors={Common:['#d5a967','#704636','#b87f56'],Rare:['#72b5b4','#315d63','#53999c'],Epic:['#a784d2','#574273','#8766b1'],Legendary:['#edc85f','#80523a','#c68c47'],Mythical:['#ed7fa7','#633962','#ba5791']};const dragonNames=['Cinder','Moss','Bracken','Pip','Ash','Saffron','Thistle','Ember','Sable','Juniper'];const initial={hatched:false,name:'',rarity:'Common',day:1,hp:100,maxHp:100,xp:0,energy:100,bond:12,level:1,damage:12,won:false,battle:null,log:'The egg pulses softly beneath the old oak.'};let state;try{state={...initial,...JSON.parse(localStorage.getItem('emberwake-save')||'{}')}}catch{state={...initial}}const $=s=>document.querySelector(s);const save=()=>localStorage.setItem('emberwake-save',JSON.stringify(state));function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2300)}function setColors(){const c=colors[state.rarity]||colors.Common;$('#dragonLight').setAttribute('stop-color',c[0]);$('#dragonDark').setAttribute('stop-color',c[1]);$('#wingLight').setAttribute('stop-color',c[2])}function render(){const h=state.hatched;$('#dayNum').textContent=String(state.day).padStart(2,'0');$('#dragonName').textContent=h?state.name:'A little one awaits';$('#dragonSubtitle').textContent=h?`${state.rarity} dragon · Level ${state.level}`:'Your dragon’s story starts today';$('#hatchBtn').textContent=h?'Meet your dragon  ✦':'Hatch your egg  →';$('#hatchBtn').classList.toggle('hidden',h);$('#levelTag').textContent=h?`LVL ${state.level}`:'EGG';$('#bondNum').textContent=h?`${state.bond}%`:'—';$('#healthText').textContent=h?`${state.hp} / ${state.maxHp}`:'—';$('#xpText').textContent=h?`${state.xp} / 100`:'—';$('#energyText').textContent=h?`${state.energy} / 100`:'—';$('#healthBar').style.width=h?`${state.hp/state.maxHp*100}%`:'0';$('#xpBar').style.width=h?`${state.xp}%`:'0';$('#energyBar').style.width=h?`${state.energy}%`:'0';$('#questBtn').disabled=!h||state.energy<15||state.hp<1||state.won;$('#questBtn').textContent=state.won?'The shadow has fallen ✓':!h?'Hatch your dragon first':state.hp<1?'Rest before you fight':state.energy<15?'Too tired to venture out':'Venture into the dark  →';$('#journalText').innerHTML=`<b>Field note:</b> ${state.log}`;setColors();save()}function modal(html){$('#modalRoot').innerHTML=`<div class="modal-backdrop"><section class="modal">${html}</section></div>`;$('#modalRoot').querySelector('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()})}function closeModal(){$('#modalRoot').innerHTML=''}function gainXp(n){state.xp+=n;if(state.xp>=100){state.xp-=100;state.level++;state.maxHp+=12;state.hp=Math.min(state.maxHp,state.hp+30);state.damage+=3;toast(`${state.name} reached level ${state.level}!`)}}
 function hatch(){if(state.hatched){toast(`${state.name} nuzzles your hand.`);return}modal(`<button class="modal-close" aria-label="Close">×</button><div class="eyebrow">A birthday blessing</div><h2>Every legend starts somewhere.</h2><p>On the day you were born, an egg appeared beneath the ancient oak. It has waited patiently for you. Inside is a dragon that will be yours alone to raise—and a rare few carry a spark no other dragon in the world has ever held.</p><div class="egg-visual">✧</div><div class="rarity-list"><span class="rarity">Common</span><span class="rarity rare">Rare</span><span class="rarity epic">Epic</span><span class="rarity legendary">Legendary</span><span class="rarity mythical">Mythical · one in the universe</span></div><div class="modal-actions" style="justify-content:center"><button class="primary" id="crackEgg">Welcome your dragon ✦</button></div><div class="tooltip" style="text-align:center">Your dragon’s rarity, colors, and name are decided when it hatches.</div>`);$('#modalRoot .modal-close').onclick=closeModal;$('#crackEgg').onclick=()=>{const r=Math.random()*100;state.rarity=r<.5?'Mythical':r<9?'Legendary':r<24?'Epic':r<52?'Rare':'Common';state.name=dragonNames[Math.floor(Math.random()*dragonNames.length)];state.hatched=true;state.log=state.rarity==='Mythical'?`A once-in-the-universe Mythical ${state.name} has hatched. The old stories were true.`:`${state.name} chose you. The bond is just beginning.`;closeModal();render();$('#dragonArt').classList.add('bounce');setTimeout(()=>$('#dragonArt').classList.remove('bounce'),600);toast(`${state.rarity} dragon ${state.name} has hatched!`)}}
