 function battleTurn(move){const b=state.battle;if(!b||state.hp<=0||b.enemyHp<=0)return;let msg='';b.turn++;if(move==='strike'){let d=state.damage+Math.floor(Math.random()*9);if(state.rarity==='Mythical')d+=18;b.enemyHp-=d;msg=`${state.name} launches a fierce flame strike for ${d} damage!`}else if(move==='guard'){state._guard=true;msg=`${state.name} shields you both, ready for the Dark Dragon’s attack.`}else{const heal=25+Math.floor(state.bond/10);state.hp=Math.min(state.maxHp,state.hp+heal);state.bond=Math.min(100,state.bond+2);msg=`You call to ${state.name}. The bond restores ${heal} vitality.`}if(b.enemyHp>0){const raw=15+Math.floor(Math.random()*12)+Math.floor(state.level/2);const hit=state._guard?Math.ceil(raw*.3):raw;state.hp=Math.max(0,state.hp-hit);state._guard=false;msg+=` The Dark Dragon strikes back for ${hit}.`}b.log=msg;render();showBattle()}

